import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Card, Table } from 'antd'
import { ArrowLeftOutlined } from '@ant-design/icons'
import { get } from 'lodash'
import moment from 'moment'

import { FeedbackListStyle } from './component.style'
import { Filters } from '.'
import { DisplayBadge, Header } from '../../../../../components/StyledComponents'
import { FeedbackTableColumns } from './constants'
import claimActions from '../../../../redux/claims/actions'

const { getFeedbackListData } = claimActions

class FeedbackList extends Component {

  state = {
    filterValues: {}
  }

  componentDidMount() {
    const { location } = this.props

    this.setState({ eventCode: get(location, 'state.eventCode') }, () => this.fetch(
      {
        startDate: get(location, 'state.startDate') || moment().clone().subtract(7, 'days').format('YYYY-MM-DD'),
        endDate: get(location, 'state.endDate') || moment().format('YYYY-MM-DD'),
        partners: get(location, 'state.partners'),
        productKey: get(location, 'state.productKey'),
        rating: get(location, 'state.rating')
      }
    ))
  }

  fetch = (values = {}) => {
    const { eventCode } = this.state

    const { startDate, endDate, partners, productKey, rating } = values;
    this.setState({ filterValues: values })
    this.props.getFeedbackListData({
      query: {
        start_date: startDate,
        end_date: endDate,
        partners: partners,
        product_key: productKey,
        rating: rating,
        event: eventCode
      }
    })
  }

  handleClickDetail = id => {
    this.props.history.push({ pathname: `/claim/${id}`, search: '' })
  }

  handleBack = () => {
    this.props.history.replace('/customer-feedback/',  {...this.state.filterValues})
  }

  render() {
    const { feedbackList = [], feedbackListLoading, location } = this.props

    return (
      <FeedbackListStyle>
        <Button
          type='primary'
          icon={<ArrowLeftOutlined />}
          onClick={this.handleBack}
        >
          Back
        </Button>
        <Card>
          <Filters
            fetch={this.fetch}
            startDate={get(location, 'state.startDate')}
            endDate={get(location, 'state.endDate')}
            partners={get(location, 'state.partners')}
            productKey={get(location, 'state.productKey')}
            rating={get(location, 'state.rating')}
          />
        </Card>
        <Card className='list-card'>
          <Header content={<div>CUSTOMER FEEDBACK <DisplayBadge count={feedbackList.length} /></div>} />
          <Table
            columns={FeedbackTableColumns(this)}
            dataSource={feedbackList}
            loading={!!feedbackListLoading}
            rowKey='claim_id'
          />
        </Card>
      </FeedbackListStyle>
    )
  }
}

export default connect(state => ({
  feedbackList: state.Claim.feedbackList,
  feedbackListLoading: state.Loading.GET_FEEDBACK_LIST_DATA
}), {
  getFeedbackListData
})(FeedbackList)
